            args['threads'] = int(argv[i])
        elif arg == '-x' or arg == '--exec':
            args['exec'] = argv[i+1:]
            break
        elif arg == '-X' or arg == '--exec-batch':
            args['exec_batch'] = argv[i+1:]
            break
        elif arg == '--':
            pos_args.extend(argv[i+1:])
            break
        elif arg.startswith('-'):
            # Handle other flags or combinations
            if arg.startswith('-tf'): args['types'].append('f')
            elif arg.startswith('-td'): args['types'].append('d')
            # This is not complete, but good enough for now
            pass
        else:
            pos_args.append(arg)
        i += 1

    if pos_args:
        args['pattern'] = pos_args[0]
        args['paths'] = pos_args[1:]
    if not args['paths']:
        args['paths'] = ["."]

    # Pattern logic
    pattern = args['pattern']
    if pattern is None or pattern == "":
        re_pattern = None
    elif args['fixed_strings']:
        re_pattern = re.escape(pattern)
    elif args['glob']:
        re_pattern = glob_to_regex(pattern)
    else:
        re_pattern = pattern

