    if args['ignore_case']:
        flags |= re.IGNORECASE
    elif not args['case_sensitive']:
        # Smart case
        if pattern and pattern.lower() == pattern:
            flags |= re.IGNORECASE

    compiled_re = None
    if re_pattern:
        try:
            compiled_re = re.compile(re_pattern, flags)
        except re.error:
            # If it's not a valid regex, maybe treat as literal?
            # Actually fd should probably report an error.
            pass

    # Traversal
    results = []
    for root_path in args['paths']:
        for root, dirs, files in os.walk(root_path, followlinks=args['follow']):
            # Depth check
