                entries.append((os.path.join(root, d), True))
            for f in files:
                entries.append((os.path.join(root, f), False))

            for path, is_dir in entries:
                # Match
                match_name = path if args['full_path'] else os.path.basename(path)
                if compiled_re is None or compiled_re.search(match_name):
                    # Type and extension filters
                    if args['extensions']:
