import os
import sys
import re
import fnmatch
from concurrent.futures import ThreadPoolExecutor

def glob_to_regex(glob_pattern):
    # fnmatch.translate produces a regex that matches the whole string
    # fd's glob usually matches the whole filename.
    return fnmatch.translate(glob_pattern)

class GitIgnore:
    def __init__(self, root_path):
        self.rules = []
        self.root_path = os.path.abspath(root_path)

    def add_file(self, gitignore_path):
        if not os.path.exists(gitignore_path):
            return
        base_dir = os.path.abspath(os.path.dirname(gitignore_path))
        with open(gitignore_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                self.rules.append((base_dir, line))

    def is_ignored(self, path):
        path = os.path.abspath(path)
        for base_dir, pattern in self.rules:
            # This is a very simplified gitignore matching
            # Real gitignore is much more complex
            if pattern.startswith('/'):
                # Match relative to base_dir
                pattern = pattern[1:]
                full_pattern = os.path.join(base_dir, pattern)
                if fnmatch.fnmatch(path, full_pattern):
                    return True
            else:
                # Match anywhere under base_dir
                if fnmatch.fnmatch(os.path.basename(path), pattern):
                    if path.startswith(base_dir):
                        return True
        return False

def get_color(path, is_dir, is_exec):
    # Basic ANSI colors
    if is_dir:
        return "\033[38;5;81m"
    if is_exec:
        return "\033[38;5;197m"
    ext = os.path.splitext(path)[1].lower()
    if ext in ('.js', '.ts', '.py', '.rs'):
        return "\033[38;5;48m"
    if ext in ('.md', '.txt'):
        return "\033[38;5;186m"
    if ext in ('.png', '.jpg', '.jpeg', '.gif', '.svg'):
        return "\033[38;5;208m"
    return ""

def main():
    argv = sys.argv[1:]
    args = {
        'pattern': None,
        'paths': [],
        'hidden': False,
        'no_ignore': False,
        'case_sensitive': False,
        'ignore_case': False,
        'glob': False,
        'fixed_strings': False,
        'absolute_path': False,
        'follow': False,
        'full_path': False,
        'print0': False,
        'max_depth': None,
        'excludes': [],
        'types': [],
        'extensions': [],
        'color': 'auto',
        'threads': os.cpu_count(),
        'exec': None,
        'exec_batch': None,
        'base_directory': None,
    }

    pos_args = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ('-H', '--hidden'):
            args['hidden'] = True
        elif arg in ('-I', '--no-ignore'):
            args['no_ignore'] = True
        elif arg in ('-u', '--unrestricted'):
            args['hidden'] = True
            args['no_ignore'] = True
        elif arg in ('-s', '--case-sensitive'):
            args['case_sensitive'] = True
        elif arg in ('-i', '--ignore-case'):
            args['ignore_case'] = True
        elif arg in ('-g', '--glob'):
            args['glob'] = True
        elif arg == '--regex':
            args['glob'] = False
        elif arg in ('-F', '--fixed-strings'):
            args['fixed_strings'] = True
        elif arg in ('-a', '--absolute-path'):
            args['absolute_path'] = True
        elif arg in ('-L', '--follow'):
            args['follow'] = True
        elif arg in ('-p', '--full-path'):
            args['full_path'] = True
        elif arg in ('-0', '--print0'):
            args['print0'] = True
        elif arg in ('-d', '--max-depth'):
            i += 1
            args['max_depth'] = int(argv[i])
        elif arg == '-x' or arg == '--exec':
            args['exec'] = argv[i+1:]
            break
        elif arg == '-X' or arg == '--exec-batch':
            args['exec_batch'] = argv[i+1:]
            break
        elif arg in ('-c', '--color'):
            i += 1
            args['color'] = argv[i]
        elif arg in ('-e', '--extension'):
            i += 1
            args['extensions'].append(argv[i])
        elif arg == '-C' or arg == '--base-directory':
            i += 1
            args['base_directory'] = argv[i]
        elif not arg.startswith('-'):
            pos_args.append(arg)
        i += 1

    if pos_args:
        args['pattern'] = pos_args[0]
        args['paths'] = pos_args[1:]
    if not args['paths']:
        args['paths'] = ["."]

    if args['base_directory']:
        os.chdir(args['base_directory'])

    pattern = args['pattern']
    compiled_re = None
    if pattern:
        if args['fixed_strings']:
            re_pattern = re.escape(pattern)
        elif args['glob']:
            re_pattern = glob_to_regex(pattern)
        else:
            re_pattern = pattern

        flags = 0
        if args['ignore_case']:
            flags |= re.IGNORECASE
        elif not args['case_sensitive']:
            if pattern.lower() == pattern:
                flags |= re.IGNORECASE
        try:
            compiled_re = re.compile(re_pattern, flags)
        except:
            compiled_re = re.compile(re.escape(pattern), flags)

    use_color = False
    if args['color'] == 'always':
        use_color = True
    elif args['color'] == 'auto':
        use_color = sys.stdout.isatty()

    gitignore = GitIgnore(".")
    if not args['no_ignore']:
        # Find .gitignore in current and parent dirs
        curr = os.path.abspath(".")
        while True:
            gi_path = os.path.join(curr, ".gitignore")
            if os.path.exists(gi_path):
                gitignore.add_file(gi_path)
            fd_path = os.path.join(curr, ".fdignore")
            if os.path.exists(fd_path):
                gitignore.add_file(fd_path)
            if os.path.exists(os.path.join(curr, ".git")):
                break
            parent = os.path.dirname(curr)
            if parent == curr:
                break
            curr = parent

    def process_entry(path, is_dir):
        # Filtering
        if not args['hidden'] and os.path.basename(path).startswith('.') and path not in args['paths']:
            return

        if not args['no_ignore'] and gitignore.is_ignored(path):
            return

        match_name = path if args['full_path'] else os.path.basename(path)
        if compiled_re and not compiled_re.search(match_name):
            return

        if args['extensions']:
            ext = os.path.splitext(path)[1].lstrip('.')
            if ext not in args['extensions']:
                return

        # Output
        out_path = path
        if args['absolute_path']:
            out_path = os.path.abspath(path)

        if use_color:
            dirname = os.path.dirname(out_path)
            basename = os.path.basename(out_path)
            if dirname and dirname != ".":
                # This coloring is simplified
                print(f"\033[38;5;81m{dirname}/\033[0m", end="")

            color = get_color(out_path, is_dir, os.access(out_path, os.X_OK) if not is_dir else False)
            if is_dir:
                print(f"{color}{basename}/\033[0m")
